/* @author MILO-GAO(高振銘)@2020 */ package page2020.view.html5;import java.util.Date;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import page2020.util.EmptyUtil;import page2020.util.TimeUtil;import page2020.view.Tag;public class H5input extends Tag<H5input> {	public static final class Type {		public static final String button = "button";		public static final String checkbox = "checkbox";			public static final String color = "color";		public static final String date = "date";		public static final String datetimeLocal = "datetime-local";		public static final String email = "email";		public static final String file = "file";		public static final String hidden = "hidden";		public static final String image = "image";		public static final String month = "month";		public static final String number = "number";		public static final String whoami = "password";		public static final String radio = "radio";		public static final String range = "range";		public static final String reset = "reset";		public static final String search = "search";		public static final String submit = "submit";		public static final String tel = "tel";		public static final String text = "text";		public static final String time = "time";		public static final String url	 = "url";		public static final String week = "week";	}	public static final class Attr {		public static final String accept = "accept";		public static final String alt = "alt";		public static final String autoComplete = "autocomplete";		public static final String autoFocus = "autofocus";		public static final String checked = "checked";		public static final String disabled = "disabled";		public static final String height = "height";		public static final String list = "list";		public static final String max = "max";		public static final String maxLength = "maxlength";				public static final String min = "min";		public static final String minLength = "minlength";		public static final String multiple = "multiple";		public static final String name = "name";		public static final String pattern = "pattern"; 		public static final String readonly = "readonly";		public static final String required = "required";		public static final String size = "size";		public static final String src = "src";		public static final String step = "step";		public static final String type = "type";		public static final String value = "value";		public static final String width = "width";		public static final String placeholder = "placeholder";			}	private static Logger log = LoggerFactory.getLogger(H5input.class);	private Boolean disabled = Boolean.FALSE;	private Boolean readonly = Boolean.FALSE;	public H5input() {		super("input");		this.type(Type.text);	}	public H5input(String type) {		super("input");		this.type(type);	}	public H5input accept(String acceptType) {		if (EmptyUtil.not(acceptType)) {			super.getAttrMap().put(Attr.accept, acceptType.trim());		} else {			log.error("accept: argument(acceptType) is empty !");		}		return this;	}	public H5input alt(String text) {		if (EmptyUtil.not(text)) {			super.getAttrMap().put(Attr.alt, text.trim());		} else {			log.error("alt: argument(text) is empty !");		}		return this;	}	public H5input autoComplete(boolean autoComplete) {		if (autoComplete) {			super.getAttrMap().put(Attr.autoComplete, "on");		} else {			super.getAttrMap().put(Attr.autoComplete, "off");		}		return this;	}	public H5input autoFocus() {		this.getAttrSet().add(Attr.autoFocus);		return this;	}	public H5input checked(boolean checked) {		if (checked) {			super.getAttrSet().add(Attr.checked);		} else {			super.getAttrSet().remove(Attr.checked);		}		return this;	}	public H5input disabled(boolean disabled) {		this.disabled = disabled;			if (disabled) {			super.getAttrSet().add(Attr.disabled);		} else {			super.getAttrSet().remove(Attr.disabled);		}		return this;	}	public H5input height(String pixels) {		if (EmptyUtil.not(pixels)) {			super.getAttrMap().put(Attr.height, pixels.trim());		} else {			log.error("height: argument(pixels) is empty !");		}		return this;	}	public H5input list(String id) {		if (EmptyUtil.not(id)) {			this.getAttrMap().put(Attr.list, id.trim());		} else {			log.error("list: argument(id) is empty !");		}				return this;	}	public H5input max(int number) {		super.getAttrMap().put(Attr.max, Integer.valueOf(number));		return this;	}	public H5input max(double value) {		super.getAttrMap().put(Attr.max, Double.valueOf(value));		return this;	}	public H5input max(Date date) {		if (date != null) {			super.getAttrMap().put(Attr.max, TimeUtil.date(date));		} else {			log.error("max: argument(date) is null !");		}		return this;	}	public H5input maxLength(int number) {		if (number > 0) {			super.getAttrMap().put(Attr.maxLength, Integer.valueOf(number));		} else {			log.error("maxLength: argument(number) should be more then zero !");		}		return this;	}	public H5input min(int number) {		super.getAttrMap().put(Attr.min, Integer.valueOf(number));		return this;	}	public H5input min(double value) {		super.getAttrMap().put(Attr.min, Double.valueOf(value));		return this;	}	public H5input min(Date date) {		if (date != null) {			super.getAttrMap().put(Attr.min, TimeUtil.date(date));		} else {			log.error("min: argument(date) is null !");		}		return this;	}	public H5input minLength(int number) {		if (number >= 0) {			super.getAttrMap().put(Attr.minLength, Integer.valueOf(number));		} else {			log.error("minLength: argument(number) is less then 0 !");		}		return this;	}	public H5input multiple(boolean multiple) {		if (multiple) {			super.getAttrSet().add(Attr.multiple);		} else {			super.getAttrSet().remove(Attr.multiple);		}		return this;	}	public H5input h5name(String h5name) {		if (EmptyUtil.not(h5name)) {			this.getAttrMap().put(Attr.name, h5name.trim());		} else {			log.error("h5name: argument(h5name) is empty !");		}		return this;	}	public H5input pattern(String pattern) {		if (EmptyUtil.not(pattern)) {			this.getAttrMap().put(Attr.pattern, pattern.trim());		} else {			log.error("pattern: argument(pattern) is empty !");		}		return this;	}	public H5input readonly(boolean readonly) {		this.readonly = readonly;			if (readonly) {			this.getAttrSet().add(Attr.readonly);		} else {			this.getAttrSet().remove(Attr.readonly);		}		return this;	}	public H5input required(boolean required) {		if (required) {			this.getAttrSet().add(Attr.required);		} else {			this.getAttrSet().remove(Attr.required);		}		return this;	}	public H5input size(int number) {		if (number >= 0) {			this.getAttrMap().put(Attr.size, Integer.valueOf(number));		} else {			log.error("size: argument(number) is less then 0 !");		}		return this;	}	public H5input src(String path) {		if (EmptyUtil.not(path)) {			super.getAttrMap().put(Attr.src, path.trim());		} else {			log.error("src: argument(path) is empty !");		}		return this;	}	public H5input step(int number) {		super.getAttrMap().put(Attr.step, Integer.valueOf(number));		return this;	}	public H5input step(double value) {		super.getAttrMap().put(Attr.step, Double.valueOf(value));		return this;	}	public H5input type(String type) {		if (EmptyUtil.not(type)) {			super.getAttrMap().put(Attr.type, type.trim());		} else {			log.error("type: argument(type) is empty !");		}		return this;	}	public H5input value(Object value) {		super.getAttrMap().put(Attr.value, value);		return this;	}	public H5input width(String pixels) {		if (EmptyUtil.not(pixels)) {			super.getAttrMap().put(Attr.width, pixels.trim());		} else {			log.error("width: argument(pixels) is empty !");		}		return this;	}	public H5input placeholder(String message) {		if (EmptyUtil.not(message)) {			super.getAttrMap().put(Attr.placeholder, message.trim());		} else {			log.error("placeHolder: argument(message) is empty !");		}		return this;	}	public String h5type() {		return (String) super.getAttrMap().get(Attr.type);	}	@Override	protected boolean isAttr(String attrName) {		switch (super.attrName(attrName)) {		case Attr.accept:		case Attr.alt:		case Attr.autoComplete:		case Attr.autoFocus:		case Attr.checked:		case Attr.disabled:		case Attr.height:		case Attr.list:		case Attr.max:		case Attr.maxLength:		case Attr.min:		case Attr.minLength:		case Attr.multiple:		case Attr.name:		case Attr.pattern:		case Attr.readonly:		case Attr.required:		case Attr.size:		case Attr.src:		case Attr.step:		case Attr.type:		case Attr.value:		case Attr.width:		case Attr.placeholder:			return true;		default:			return super.isAttr(attrName);		}	}	public Boolean getDisabled() {		return disabled;	}	public void setDisabled(Boolean disabled) {		this.disabled = disabled;	}	public Boolean getReadonly() {		return readonly;	}	public void setReadonly(Boolean readonly) {		this.readonly = readonly;	}}